<script> lucide.createIcons(); const isStoreOpen = true; window.onload = function() { if (!isStoreOpen) { setTimeout(() => { openStoreClosedModal(); }, 1000); } }; function navigateTo(screenId) { ['home-screen','product-screen','account-screen','info-screen','orders-screen'].forEach(id => { document.getElementById(id).classList.add('hidden'); if(id === 'product-screen') document.getElementById(id).classList.remove('md:flex'); }); const activeScreen = document.getElementById(screenId); activeScreen.classList.remove('hidden'); if(screenId === 'product-screen') activeScreen.classList.add('md:flex'); window.scrollTo(0, 0); lucide.createIcons(); } function toggleModal(modalId) { const modal = document.getElementById(modalId); if (modal.classList.contains('hidden')) { modal.classList.remove('hidden'); modal.classList.add('modal-active'); if(modal.querySelector('.modal-content')) { setTimeout(() => { modal.querySelector('.modal-content').style.transform = 'translateY(0)'; }, 10); } } else { if(modal.querySelector('.modal-content')) { modal.querySelector('.modal-content').style.transform = 'translateY(100%)'; } modal.classList.remove('modal-active'); setTimeout(() => { modal.classList.add('hidden'); }, 300); } } function openStoreClosedModal() { const modal = document.getElementById('store-closed-modal'); modal.classList.remove('hidden'); setTimeout(() => { modal.classList.add('modal-active'); }, 10); } function closeStoreClosedModal() { const modal = document.getElementById('store-closed-modal'); modal.classList.remove('modal-active'); setTimeout(() => { modal.classList.add('hidden'); }, 300); } function checkStoreAndAddToCart() { if (!isStoreOpen) { openStoreClosedModal(); } else { alert('Adicionado!'); } } function checkStoreAndCheckout() { const cartModal = document.getElementById('cart-modal'); const isCartOpen = !cartModal.classList.contains('hidden'); if (!isStoreOpen) { if (isCartOpen) toggleModal('cart-modal'); setTimeout(openStoreClosedModal, 300); } else { if (isCartOpen) toggleModal('cart-modal'); setTimeout(() => { const modal = document.getElementById('success-modal'); modal.classList.remove('hidden'); setTimeout(() => { modal.classList.add('modal-active'); }, 10); }, isCartOpen ? 400 : 100); } } function closeSuccessAndGoToOrders() { const modal = document.getElementById('success-modal'); modal.classList.remove('modal-active'); setTimeout(() => { modal.classList.add('hidden'); navigateTo('orders-screen'); }, 300); } function performLogout() { toggleModal('logout-modal'); setTimeout(() => { navigateTo('home-screen'); }, 300); } </script>
